const s = H.story('waterfront', H.progress('waterfront', 'A1'));
const v = !!s.monumentShrouded?.();
return { ok: v, detail: 'shrouded ' + v };

const a = H.story('waterfront', H.progress('waterfront', 'B2'));
const before = !!a.monumentShrouded?.();
const s = await H.certify({});
await H.settle(s);
const has = typeof s.monumentShrouded === 'function';
const after = has ? !!s.monumentShrouded() : null;
return { ok: before && has && after === false, detail: 'before ' + before + ', after ' + after };

const flag = 'world.monumentShroud' in H.STORY.P7SIM;
const a = H.arcade('waterfront');
const s6 = H.sim6('waterfront');
const arc = !!a.monumentShrouded?.();
const m6 = !!H.scene(s6, 'B2')?.dummyMonument;
return { ok: flag && !arc && !m6, detail: 'flag ' + flag + ', arcade shrouded ' + arc + ', 6.10 monument ' + m6 };

await G.openStory(await G.certifyProgress({}));
const v = await G.eval(() => { const s = window.__dummies?.sim; return { tile: s?.screenName?.(), shrouded: !!s?.monumentShrouded?.() }; });
await G.shot('shroud_b2');
return { ok: v.tile === 'B2' && v.shrouded, detail: JSON.stringify(v) };

const s = await H.certify({});
await H.runTo(s, (x) => x.phase === 'unveil' || x.phase === 'ending', 900);
return { ok: s.phase === 'unveil', detail: 'phase ' + s.phase };

const s = await H.certify({ points: 123456, chassis: 40, t: 3600, bestCombo: 7 });
await H.runTo(s, (x) => x.phase === 'unveil' || x.phase === 'ending', 900);
const p = s.unveil?.plaque, pr = s.story;
const ok = !!p && p.chassis === pr.chassis && Math.round(p.points) === Math.round(pr.points) && (pr.bestCombo || 0) >= 7 && p.bestCombo === pr.bestCombo && Math.abs((p.t ?? -1e9) - pr.t) < 5;
return { ok, detail: JSON.stringify(p || null) + ' / progress chassis ' + pr.chassis + ' points ' + Math.round(pr.points) + ' combo ' + pr.bestCombo + ' t ' + pr.t };

const s = await H.certify({});
await H.runTo(s, (x) => x.phase === 'unveil' || x.phase === 'ending', 900);
const n = H.ev(s, 'unveil').length;
return { ok: n === 1 && s.story.complete === true, detail: 'unveil events ' + n + ', complete ' + s.story.complete };

const s = H.story('monument', H.progress('monument', 'A1'));
await H.ready(s);
H.kill(s, { kind: 'dash', cls: 'sedan', combo: 3 });
const b = s.story.bestCombo;
return { ok: b === 3, detail: 'bestCombo ' + b };

await G.openStory(await G.certifyProgress({}));
await G.lastWriteOff();
const ok = await G.waitFor(() => window.__dummies?.sim?.phase === 'unveil', 8000);
await G.shot('unveil');
const ph = await G.eval(() => window.__dummies?.sim?.phase);
return { ok, detail: 'phase ' + ph };

const s = await H.certify({});
await H.runTo(s, (x) => x.phase === 'unveil' || x.phase === 'ending', 900);
s.continueUnveil?.();
await H.runTo(s, (x) => x.phase === 'voyage' || x.phase === 'ending', 120);
return { ok: s.phase === 'voyage' && !!s.rescue?.voyage, detail: 'phase ' + s.phase + ', voyage ' + !!s.rescue?.voyage };

const s = await H.certify({});
await H.runTo(s, (x) => { if (x.phase === 'unveil') x.continueUnveil?.(); return x.phase === 'ending'; }, 4800);
const v = H.ev(s, 'voyage'), e = H.ev(s, 'voyage-end');
const ok = v.length === 1 && v[0].to === 'B3' && e.length === 1 && s.screenName() === 'B3' && s.run.ending?.kind === 'Certified';
return { ok, detail: 'voyage ' + v.length + ', end ' + e.length + ', tile ' + s.screenName() + ', ending ' + (s.run.ending?.kind || null) };

const built = typeof H.STORY.StorySim.prototype.continueUnveil === 'function';
const a = H.arcade('waterfront');
await H.step(a, 300);
const bad = a.phase === 'unveil' || a.phase === 'voyage' || H.ev(a, 'voyage').length > 0;
return { ok: built && !bad, detail: 'built ' + built + ', arcade phase ' + a.phase };

await G.openStory(await G.certifyProgress({}));
await G.lastWriteOff();
const u = await G.waitFor(() => window.__dummies?.sim?.phase === 'unveil', 8000);
let ok = false;
if (u) { await G.wait(1500); await G.press('Space'); ok = await G.waitFor(() => window.__dummies?.sim?.phase === 'voyage', 4000); }
await G.wait(1000);
await G.shot('voyage');
return { ok, detail: 'unveil ' + u + ', voyage ' + ok };

const s = H.story('waterfront', H.progress('waterfront', 'B3'));
const sh = H.scene(s, 'B3')?.containerShip;
return { ok: !!sh && sh.face === true && (sh.crates || 0) > 0, detail: JSON.stringify(sh || null) };

const s = H.story('waterfront', H.progress('waterfront', 'B3'));
const has = !!H.scene(s, 'B3')?.containerShip;
const s6 = H.sim6('waterfront');
const six = !!H.scene(s6, 'B3')?.containerShip;
return { ok: has && !six, detail: 'story ' + has + ', 6.10 ' + six };

await G.openStory(await G.certifyProgress({}));
await G.lastWriteOff();
const u = await G.waitFor(() => window.__dummies?.sim?.phase === 'unveil', 8000);
let v = false;
if (u) { await G.wait(1500); await G.press('Space'); v = await G.waitFor(() => window.__dummies?.sim?.phase === 'voyage', 4000); }
const n = v ? await G.eval(() => { const c = window.__dummiesUI?.credits?.(); return Array.isArray(c) ? c.length : 0; }) : 0;
await G.shot('credits');
return { ok: v && n > 0, detail: 'voyage ' + v + ', lines ' + n };

const s = H.story('monument', H.progress('monument', 'A1'));
if (!s.models?.sedan) return { ok: false, detail: 'no sedan model' };
s.models.sedan.applied = 2;
s.syncProgress();
const v = s.story.learning?.sedan?.applied;
return { ok: v === 2, detail: 'learning.sedan.applied ' + v };

const f = H.STORY.secondMarket;
if (typeof f !== 'function') return { ok: false, detail: 'no secondMarket' };
const pr = H.progress('waterfront', 'B2', { learning: { sedan: { applied: 3, standoffApplied: 0 } } });
pr.complete = true;
const p2 = f(JSON.parse(JSON.stringify(pr)));
const none = Object.values(p2.done || {}).every((a) => !a.length);
return { ok: p2.district === 'monument' && p2.complete === false && none && p2.learning?.sedan?.applied === 3, detail: JSON.stringify({ d: p2.district, c: p2.complete, none, l: p2.learning }) };

const f = H.STORY.secondMarket;
if (typeof f !== 'function') return { ok: false, detail: 'no secondMarket' };
const pr = H.progress('waterfront', 'B2', { learning: { sedan: { applied: 3, standoffApplied: 0 } } });
pr.complete = true;
const n = H.story('monument', f(pr));
const v = n.models?.sedan?.applied;
return { ok: v === 3, detail: 'sedan applied ' + v };

const s = H.story('monument', H.progress('monument', 'A1'));
await H.ready(s);
H.kill(s);
const st = s.report?.story;
return { ok: !!st?.cleared && st.grade != null, detail: 'cleared ' + !!st?.cleared + ', grade ' + (st?.grade ?? null) };

const s = H.story('monument', H.progress('monument', 'A1'));
await H.ready(s);
H.kill(s);
const g = s.story.tileGrades?.['monument:A1'];
return { ok: g != null, detail: 'grade ' + (g ?? null) };

await G.openStory(await G.certifyProgress({}));
const w = await G.eval(() => { const f = window.__dummiesUI?.barkPlace; return f ? String(f(window.__dummies.sim)) : null; });
const ok = !!w && (/\bB2\b/.test(w) || /circus/i.test(w)) && !/^waterfront$/i.test(w.trim());
return { ok, detail: 'place ' + w };

const s = H.story('parkland', H.progress('parkland', 'B1'));
const n = H.scene(s, 'B1')?.game?.dropGaps?.length || 0;
return { ok: n > 0, detail: 'B1 drop gaps ' + n };

const flag = 'world.parklandRow1Street' in H.STORY.P7SIM;
const s6 = H.sim6('parkland');
const n6 = H.scene(s6, 'B1')?.game?.dropGaps?.length || 0;
return { ok: flag && n6 === 0, detail: 'flag ' + flag + ', 6.10 gaps ' + n6 };

const D = H.STORY.DIST;
const ok = D.length === 3 && D.every((d) => !!d.act) && H.STORY.TOTAL === 27 && D.every((d) => d.order.every((t) => !!d.tiles[t]?.tale));
return { ok, detail: 'districts ' + D.length + ', tiles ' + H.STORY.TOTAL };

const e = H.STORY.DATA?.ending;
const want = 'Your model has passed. It will now be manufactured. A Farsight drone carries you over the river to a container ship. Destination: a market far away. Please remain still for the voyage.';
return { ok: e === want, detail: String(e).slice(0, 60) };

const s = await H.certify({});
await H.runTo(s, (x) => { if (x.phase === 'unveil') x.continueUnveil?.(); return x.phase === 'ending'; }, 4800);
return { ok: s.phase === 'ending' && s.run.ending?.kind === 'Certified' && s.story.complete === true, detail: 'phase ' + s.phase + ', ending ' + (s.run.ending?.kind || null) };

await G.openStory(await G.certifyProgress({}));
await G.lastWriteOff();
let ok = false;
for (let i = 0; i < 15 && !ok; i++) { ok = await G.waitFor(() => window.__dummies?.sim?.phase === 'ending', 1000); if (!ok && await G.eval(() => window.__dummies?.sim?.phase === 'unveil')) await G.press('Space'); }
await G.shot('ending');
return { ok, detail: 'phase ' + await G.eval(() => window.__dummies?.sim?.phase) };
